/**
 * Time budgets for handlers folded into one dispatcher process.
 *
 * Each handler used to be its own process that CC killed at its hooks.json
 * timeout. In one process nothing kills it, so the dispatcher races it
 * against its budget instead and moves on; the abandoned work keeps running
 * only until run-hook.mjs exits after the dispatcher's output (EXIT_AFTER_EMIT).
 *
 * A timer cannot interrupt synchronous work on the same event loop, so this
 * bounds async work only. Blocking calls in folded handlers carry their own
 * child-process timeout (asserted by __tests__/lib/dispatcher-sync-bounds),
 * and a result that arrives late is discarded.
 */

export const TIMED_OUT: unique symbol = Symbol('timed-out');

/** Settle with the work's value, or TIMED_OUT once `ms` pass first. A throw still rejects. */
export async function withBudget<T>(start: () => T | Promise<T>, ms: number): Promise<T | typeof TIMED_OUT> {
  if (ms <= 0) return TIMED_OUT;
  const started = Date.now();
  const work = Promise.resolve().then(start);
  // An abandoned rejection must not surface later as an unhandled rejection.
  work.catch(() => {});
  let timer: ReturnType<typeof setTimeout> | undefined;
  const expiry = new Promise<typeof TIMED_OUT>((resolve) => {
    timer = setTimeout(() => resolve(TIMED_OUT), ms);
  });
  try {
    const r = await Promise.race([work, expiry]);
    // Synchronous work blocks the timer, so it can return after its budget
    // with the race still won. A late result never decides.
    return Date.now() - started > ms ? TIMED_OUT : r;
  } finally {
    clearTimeout(timer);
  }
}
